"""Execution-grounded text-to-SQL harness.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}      (hint is BIRD's evidence; "" for Spider)
  env.chat(messages, max_tokens=None) -> str     policy call (capped per task: env.max_calls)
  env.schema(db_id) -> str                       CREATE statements of the database
  env.execute(sql, max_rows=20) -> dict          read-only run: {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str                 column descriptions if the dataset ships them, else ""
  env.prompt(name) -> str                        text of a file in this harness
  env.config -> dict                             parsed config.json

Strategy: draft -> execute -> (only if the draft errors or returns nothing) build generic
diagnostics about the real stored values / join keys -> one repair call. Nothing here is
specific to any database, table or task: every probe is derived from the draft itself and
from the schema.
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
CREATE_RE = re.compile(
    r"CREATE\s+(?:TEMP\s+|TEMPORARY\s+)?(?:TABLE|VIEW)\s+(?:IF\s+NOT\s+EXISTS\s+)?[\"'`\[]?(\w+)",
    re.I,
)
COL_RE = re.compile(r"^\s*[\"'`\[]?(\w+)[\"'`\]]?\s+([A-Za-z][\w ]*)")
LIT_RE = re.compile(r"'((?:[^']|'')*)'")
REF_RE = re.compile(r"\b(?:FROM|JOIN)\s+[\"'`\[]?(\w+)", re.I)
EQ_RE = re.compile(r"(\w+)\.(\w+)\s*=\s*(\w+)\.(\w+)")
SKIP_COLS = {"PRIMARY", "FOREIGN", "UNIQUE", "CHECK", "CONSTRAINT", "KEY"}


def extract_sql(text):
    """Last complete sql block wins; tolerate a truncated final block."""
    text = text or ""
    blocks = [b.strip() for b in SQL_BLOCK.findall(text) if b.strip()]
    if blocks:
        return _clean(blocks[-1])
    opens = list(re.finditer(r"```(?:sql|sqlite)?[ \t]*\r?\n?", text, re.I))
    if opens:
        tail = text[opens[-1].end():].strip()
        if tail:
            return _clean(tail)
    return _clean(text)


def _clean(s):
    s = (s or "").strip()
    s = re.sub(r"^```\w*", "", s).strip()
    s = s.rstrip("`").strip()
    return s.rstrip(";").strip()


def parse_schema(schema_text):
    """[(table, [(column, type), ...]), ...] from CREATE statements."""
    out = []
    for m in re.finditer(r"CREATE\s+[^(]*?\(", schema_text or "", re.I):
        head = CREATE_RE.search(m.group(0))
        if not head:
            continue
        name = head.group(1)
        i = m.end()
        depth, start = 1, i
        while i < len(schema_text) and depth:
            c = schema_text[i]
            if c == "(":
                depth += 1
            elif c == ")":
                depth -= 1
            i += 1
        body = schema_text[start:i - 1]
        parts, buf, d = [], "", 0
        for c in body:
            if c == "(":
                d += 1
            elif c == ")":
                d -= 1
            if c == "," and d == 0:
                parts.append(buf)
                buf = ""
            else:
                buf += c
        parts.append(buf)
        cols = []
        for p in parts:
            cm = COL_RE.match(p)
            if cm and cm.group(1).upper() not in SKIP_COLS:
                cols.append((cm.group(1), cm.group(2).strip().upper()))
        out.append((name, cols))
    return out


def _is_text(typ):
    t = (typ or "").upper()
    if any(k in t for k in ("INT", "REAL", "FLOA", "DOUB", "NUM", "DEC", "BOOL", "DATE", "TIME")):
        return False
    return True


def _lit_probe(table, col, val):
    v = val.replace("'", "''")
    return (
        "SELECT '%s.%s' AS location, CAST(\"%s\" AS TEXT) AS stored_value, COUNT(*) AS n_matches "
        "FROM \"%s\" WHERE \"%s\" LIKE '%%%s%%' GROUP BY 2 ORDER BY n_matches DESC LIMIT 5"
        % (table, col, col, table, col, v)
    )


def _sample_probe(table, col):
    return (
        "SELECT '%s.%s' AS location, CAST(\"%s\" AS TEXT) AS stored_value, COUNT(*) AS n "
        "FROM \"%s\" GROUP BY 2 ORDER BY n DESC LIMIT 8" % (table, col, col, table)
    )


def _key_probe(t1, c1, t2, c2):
    return (
        "SELECT '%s.%s' AS left_key, (SELECT COUNT(*) FROM \"%s\") AS left_rows, "
        "(SELECT COUNT(*) FROM \"%s\" a JOIN \"%s\" b ON a.\"%s\" = b.\"%s\") AS joined_rows, "
        "(SELECT CAST(\"%s\" AS TEXT) FROM \"%s\" LIMIT 3) AS left_sample, "
        "(SELECT CAST(\"%s\" AS TEXT) FROM \"%s\" LIMIT 3) AS right_sample"
        % (t1 + "." + c1 + " = " + t2 + "." + c2, t1, t1, t2, c1, c2, c1, t1, c2, t2)
    )


def build_diagnostics(sql, result, tables, env, cfg):
    """Generic, read-only probes explaining why a draft errored or matched nothing."""
    lines, probes = [], []
    err = (result or {}).get("error") or ""
    if err:
        lines.append("SQLite error: %s" % err)

    by_name = {t.lower(): (t, cols) for t, cols in tables}
    refs = []
    for r in REF_RE.findall(sql or ""):
        if r.lower() in by_name and r.lower() not in [x.lower() for x in refs]:
            refs.append(by_name[r.lower()][0])

    lits = [v for v in LIT_RE.findall(sql or "") if v.strip()]
    seen = set()
    for val in lits[:3]:
        core = re.sub(r"[^A-Za-z0-9]+", " ", val).strip()
        if len(core) < 3:
            continue
        token = sorted(core.split(), key=len)[-1]
        for t in refs:
            for c, typ in by_name[t.lower()][1]:
                if not _is_text(typ):
                    continue
                key = (t.lower(), c.lower(), token.lower())
                if key in seen:
                    continue
                seen.add(key)
                probes.append(_lit_probe(t, c, token))

    # equality predicates in the draft may use the wrong key columns: check overlap
    aliases = {}
    for tm in re.finditer(r"\b(?:FROM|JOIN)\s+[\"'`\[]?(\w+)[\"'`\]]?(?:\s+AS\s+(\w+)|\s+(?!ON|WHERE|JOIN|LEFT|RIGHT|INNER|OUTER|FULL|CROSS|GROUP|ORDER|LIMIT|UNION|SET|USING)(\w+))?", sql or "", re.I):
        tbl = tm.group(1)
        al = tm.group(2) or tm.group(3) or tbl
        if tbl.lower() in by_name:
            aliases[al.lower()] = by_name[tbl.lower()][0]
    for a1, c1, a2, c2 in EQ_RE.findall(sql or "")[:2]:
        t1, t2 = aliases.get(a1.lower()), aliases.get(a2.lower())
        if not t1 or not t2 or t1 == t2:
            continue
        cols1 = {c.lower() for c, _ in by_name[t1.lower()][1]}
        cols2 = {c.lower() for c, _ in by_name[t2.lower()][1]}
        if c1.lower() in cols1 and c2.lower() in cols2:
            probes.append(_key_probe(t1, c1, t2, c2))

    if not probes:
        for t in refs[:2]:
            for c, typ in by_name[t.lower()][1][:6]:
                if _is_text(typ):
                    probes.append(_sample_probe(t, c))

    budget = int(cfg.get("probe_budget", 8))
    for p in probes[:budget]:
        try:
            r = env.execute(p, max_rows=8)
        except Exception:
            continue
        if not r or not r.get("ok"):
            continue
        rows = r.get("rows") or []
        if not rows:
            lines.append("%s -> no matching rows anywhere in that column" % p.split(" AS ")[0])
            continue
        lines.append("probe result columns=%s rows=%s" % (r.get("columns"), rows))
    return "\n".join(lines)[:4000]


def solve(task, env):
    cfg = env.config or {}
    db = task["db_id"]
    schema = env.schema(db)
    user = "Database: %s\n\nSchema:\n%s\n\nQuestion: %s" % (db, schema, task["question"])
    hint = task.get("hint") or ""
    if hint:
        user += "\nHint (authoritative domain knowledge / formulas): %s" % hint
    desc = ""
    try:
        desc = env.descriptions(db) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += "\n\nColumn descriptions:\n%s" % desc.strip()[:3000]

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    max_tokens = cfg.get("max_tokens", 1200)
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)
    if not sql:
        return {"sql": "SELECT 1"}

    max_calls = getattr(env, "max_calls", 2) or 2
    if max_calls < 2:
        return {"sql": sql}

    try:
        res = env.execute(sql, max_rows=20)
    except Exception:
        res = {"ok": False, "error": "execution failed", "rows": [], "n_rows": 0}

    ok = bool(res.get("ok"))
    nrows = res.get("n_rows", len(res.get("rows") or []))
    if ok and nrows > 0:
        return {"sql": sql}

    tables = parse_schema(schema)
    diag = build_diagnostics(sql, res, tables, env, cfg)
    followup = (
        "Your draft query was executed on the real database.\n\nDraft:\n```sql\n%s\n```\n\n"
        "Outcome: %s\n\nDiagnostics from read-only probes on the actual data:\n%s\n\n"
        "An empty result usually means a filter value does not match how values are stored "
        "(case, spacing, punctuation, abbreviations), the filter uses the wrong column "
        "(e.g. a short code/name column instead of the descriptive one), or a join uses the "
        "wrong key columns. Use the probe evidence above to pick the real stored values and "
        "the correct columns/keys. If the question genuinely has no matching rows, keep the "
        "query semantically faithful anyway. Also re-check that the SELECT list returns exactly "
        "what the question asks for (all attributes of an entity when it asks for its details/"
        "information, one column when it asks for a single attribute).\n"
        "Return the corrected final query in a single ```sql code block."
        % (sql, ("error: %s" % res.get("error")) if not ok else "0 rows returned", diag or "(none)")
    )
    messages.append({"role": "assistant", "content": reply})
    messages.append({"role": "user", "content": followup})
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    try:
        res2 = env.execute(sql2, max_rows=20)
    except Exception:
        res2 = {"ok": False, "n_rows": 0}
    if not res2.get("ok"):
        return {"sql": sql}
    return {"sql": sql2}

